    'settings.english': 'English', 'settings.hindi': 'हिन्दी', 'sources.title': 'हमारे डेटा की जानकारी', 'sources.close': 'डेटा स्रोत बंद करें',
    'sources.weather': 'मौसम और पूर्वानुमान', 'sources.geography': 'भूगोल और रडार',
    'sources.weatherBody': '{{provider}} मॉडल-आधारित मौजूदा मौसम, घंटे-दर-घंटे पूर्वानुमान और 7 दिनों की जानकारी देता है। ये स्थानीय मौसम केंद्र के माप नहीं हैं। पूर्वानुमान 10 मिनट तक कैश रहता है।',
    'sources.geographyBody': 'नक्शे और भूगोल का डेटा: {{osm}}। पिछली वर्षा का रडार: {{radar}}। कवरेज बदलता है, खासकर भारत में; खाली रडार का अर्थ बारिश न होना नहीं है।',
    'sources.layersBody': 'तापमान, बादल, हवा, आर्द्रता और दबाव Open-Meteo के मॉडल-बिंदु दिखाते हैं; निरंतर उपग्रह या रडार चित्र नहीं। नया नमूना लेने के लिए नक्शा खिसकाएँ। समय प्रदाता के मॉडल का है।',
    'sources.atmosphereBody': '{{provider}} उपलब्ध होने पर प्रति घंटे के मॉडल-सांद्रता मान देता है। SO₂, NO₂, PM2.5, PM10 और ओज़ोन मौसम केंद्र के माप या वर्षा-जल pH नहीं हैं। मॉडल ग्रिड यूरोप में लगभग 11 km और दुनिया के अन्य हिस्सों में लगभग 45 km है; हर जवाब में इस्तेमाल मॉडल की पहचान नहीं दी जाती। बारिश अलग पूर्वानुमान संदर्भ है।',
    'sources.assistantBody': 'WeatherGPT नियम-आधारित भाषा विश्लेषण और मौसम नियम चलाता है; यह जनरेटिव AI नहीं है। जवाब लोड किए गए पूर्वानुमान पर आधारित हैं। सलाह आधिकारिक चेतावनी नहीं है। ब्राउज़र की आवाज़ सुविधा उसकी अपनी सेवा का उपयोग कर सकती है।',
    'sources.safetyBody': 'सार्वजनिक सेवाएँ देर से काम कर सकती हैं, सीमित हो सकती हैं या बंद हो सकती हैं। सुरक्षा से जुड़े निर्णय से पहले आधिकारिक चेतावनी देखें। बिजली गिरने की पहचान या तूफ़ान का रास्ता बताने की सुविधा जुड़ी नहीं है। व्यावसायिक उपयोग से पहले सेवा की शर्तें जाँचें।',
    'sources.searchBody': 'जगह खोजने के लिए Open-Meteo, Photon और (उपयोगकर्ता की सटीक गाँव खोज पर) {{nominatim}} का उपयोग होता है। नक्शे/भूगोल का डेटा © {{osm}}। एक जैसे नाम विकल्पों में दिखते हैं; ऐप चुपचाप एक नहीं चुनता।',
    'sources.rainPHBody': 'वर्षा-जल pH, मिट्टी का pH और सिंचाई के पानी की गुणवत्ता अलग-अलग माप हैं। वर्तमान स्थानीय वर्षा-जल pH फ़ीड नहीं है; माप न होना अज्ञात स्थिति है। उपयोगकर्ता के नमूने इसी डिवाइस पर रहते हैं। ऐप प्रदूषकों से pH नहीं निकालता और वर्षा-जल के आधार पर मिट्टी के उपचार की सलाह नहीं देता।',
    'sources.cropBody': 'पूर्वानुमान स्क्रीन तय मौसम सीमाओं का उपयोग करते हैं; ये आधिकारिक फसल-क्षति सीमाएँ नहीं हैं। फसल सलाह का स्रोत बताया जाता है या उसे सामान्य सावधानी कहा जाता है। कीटनाशक/खाद की मात्रा नहीं बताई जाती। उत्पाद संबंधी निर्णय के लिए स्थानीय कृषि विभाग या KVK से पूछें।',
    'sources.resolutionBody': 'Open-Meteo क्षेत्रीय और वैश्विक मॉडल की रिज़ॉल्यूशन सीमा बताता है, लेकिन किसी मान के पीछे का मॉडल नहीं बताता। ग्रिड का अनुमान खेत का माप नहीं है। देखें: {{provider}}।', 'sources.layers': 'मानचित्र परतें',
    'sources.atmosphere': 'वायुमंडलीय निगरानी', 'sources.assistant': 'सहायक और सलाह', 'sources.safety': 'डेमो; सुरक्षा निर्णयों के लिए नहीं',
    'sources.search': 'गाँव और जगह की खोज', 'sources.rainPH': 'बारिश का pH, मिट्टी का pH और सिंचाई का पानी', 'sources.crop': 'फसल संबंधी सावधानियाँ', 'sources.resolution': 'स्थानिक विस्तार',
    'footer.tagline': 'थोड़ी और स्पष्टता।', 'footer.created': 'निर्माता', 'footer.copyright': 'सर्वाधिकार सुरक्षित, Samyak',
