let activeLocale = 'en';
export function getLocale() { return activeLocale; }
export function setLocale(locale) { activeLocale = locale === 'hi' ? 'hi' : 'en'; return activeLocale; }
export function t(key, params = {}, locale = activeLocale) {
  const value = messages[locale]?.[key] ?? messages.en[key] ?? key;
  if (Array.isArray(value)) return value;
  return String(value).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, name) => String(params[name] ?? ''));
}
export function plural(forms, count, params = {}, locale = activeLocale) {
  const form = new Intl.PluralRules(locale === 'hi' ? 'hi-IN-u-nu-deva' : 'en-IN').select(count);
  const text = forms?.[form] ?? forms?.other ?? '';
  return String(text).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, name) => String(name === 'count' ? formatNumber(count,{},locale) : params[name] ?? ''));
}
export function tPlural(key, count, params = {}, locale = activeLocale) {
  const forms=messages[locale]?.[key] ?? messages.en[key];
  if (!forms || typeof forms !== 'object' || Array.isArray(forms)) return t(key,{...params,count},locale);
  return plural(forms,count,params,locale);
}
export function formatNumber(value, options = {}, locale = activeLocale) {
  return new Intl.NumberFormat(locale === 'hi' ? 'hi-IN-u-nu-deva' : 'en-IN', options).format(value);
}
export function formatDate(value, options = {}, locale = activeLocale) {
  return new Intl.DateTimeFormat(locale === 'hi' ? 'hi-IN-u-nu-deva' : 'en-IN', options).format(value instanceof Date ? value : new Date(value));
}
function assignDirectText(element, value) {
  const values = Array.isArray(value) ? value : [value];
  const nodes = [...element.childNodes].filter(node => node.nodeType === 3 && node.nodeValue.trim());
  if (!nodes.length) { element.textContent = values.join(' '); return; }
  nodes.forEach((node, index) => { node.nodeValue = values[index] ?? ''; });
}
function labelFor(control) {
  const id = control.id;
  return id ? control.closest('label')?.childNodes : null;
}
export function applyTranslations(root = document, locale = activeLocale) {
  if (root.documentElement) root.documentElement.lang = locale;
  const select = root.querySelector?.('#global-language');
  if (select) select.value = locale;
  for (const [key, selector, mode = 'text'] of STATIC_BINDINGS) {
    const element = root.querySelector?.(selector);
    if (!element) continue;
    const value = t(key, {}, locale);
    if (mode === 'placeholder' || mode === 'aria-label' || mode === 'title') element.setAttribute(mode, String(value));
    else if (mode === 'label') {
      const label = element.closest('label');
      if (label) {
        const text = [...label.childNodes].find(node => node.nodeType === 3 && node.nodeValue.trim());
        if (text) text.nodeValue = ` ${String(value)} `;
      }
    } else if (mode === 'parentText') {
      const label = element.parentElement;
      if (label) assignDirectText(label, value);
    } else if (mode === 'segments') assignDirectText(element, value);
    else assignDirectText(element, value);
  }
  root.querySelectorAll?.('[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria]').forEach(element => {
    if (element.dataset.i18n) assignDirectText(element, t(element.dataset.i18n, {}, locale));
    for (const [attribute, key] of [['placeholder','i18nPlaceholder'],['title','i18nTitle'],['aria-label','i18nAria']]) {
      if (element.dataset[key]) element.setAttribute(attribute, t(element.dataset[key], {}, locale));
    }
  });
}

export function missingTranslationKeys() {
  return Object.keys(messages.en).filter(key => !(key in messages.hi));
}
export function missingBindingKeys() {
  return [...new Set(STATIC_BINDINGS.map(([key]) => key))].filter(key => !(key in messages.en) || !(key in messages.hi));
}
export function unresolvedStaticBindings(root = document) {
  const selectors = [...new Set(STATIC_BINDINGS.map(([,selector]) => selector))];
  return selectors.filter(selector => { try { return !root.querySelector(selector); } catch { return true; } });
}

export default { t, setLocale, getLocale, applyTranslations, formatNumber, formatDate, messages };
